find the error string coneHeads(string str) {
    // Base case: If the string is empty, return an empty string.
    if (str.length() == 0) {
        return "";
    }
    else {
        // If the first character is '<', start recording and keep going.
        if (str.substr(0,1) == "<") {
            return str.substr(0,1) + coneHeads(str.substr(1, str.length() -1));
        }
        // If the first character is '>', stop recording and end the recursion.
        else if (str.substr(0,1) == ">") {
            return  str.substr(0,1);
        }
        // If we are recording (i.e., the first character of the remaining string is not '<'),
        // continue recording.
        else if (str.substr(0,1) != "<" && str.substr(0,1) != ">") {
            return str.substr(0,1) + coneHeads(str.substr(1, str.length() -1)); // TODO: This is not working.
        }
        // If we are not recording, keep going without recording.
        else {
            return coneHeads(str.substr(1, str.length() -1));
        }
    }
}

