function getRotationFromIndex(originalText: string, index: number): string {
   const colorRegex = /&[0-9a-fk-or]/gi;
   const matches = originalText.match(colorRegex);
   if (matches === null) {
      return originalText;
   }

   const colorBlocks = originalText.split(colorRegex);
   const colorCodes = originalText.match(colorRegex);
   let result = '';
   let currentIndex = index % (originalText.length - colorCodes.length);
   let currentColorIndex = 0;
   let plainTextIndex = 0;

   while (result.length < originalText.length) {
      if (currentColorIndex < colorBlocks.length && plainTextIndex === currentIndex) {
         result += colorCodes[currentColorIndex];
         currentColorIndex++;
         currentIndex += colorBlocks[currentColorIndex].length;
      } else {
         result += originalText[plainTextIndex];
         plainTextIndex++;
         if (plainTextIndex >= originalText.length) {
            plainTextIndex = 0;
         }
      }
   }

   return result;
}

