function Get-WordCount ($filePath, $stopwords) {
    $wordCount = @{}

    $content = Get-Content $filePath -Raw
    $words = $content -split '\s+' | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ -and !$stopwords.Contains($_) }

    foreach ($word in $words) {
        if ($wordCount.ContainsKey($word)) {
            $wordCount[$word]++
        } else {
            $wordCount[$word] = 1
        }
    }

    return $wordCount
