object ApiKeyService {

  def apply[F[_]: Sync](recruiterService: RecruiterService[F], repository: ApiKeyRepository[F]): ApiKeyService[F] =
    new ApiKeyService[F] {

      override def generateKey(bearerToken: BearerToken)(x: Unit): F[Either[ErrorMessage, ApiKey]] = (for {
        recruiter <- recruiterService.getRecruiter(AccessToken(bearerToken.token))
        key       <- ApiKey.generate
        _         <- repository.storeKey(recruiter.salesforceId, key)
      } yield key.asRight[ErrorMessage]).recover {
        case RecruiterUnauthorized(message) => Unauthorized(message).asLeft
        case RecruiterForbidden(message)    => Forbidden(message).asLeft
      }
    }
}

