impl Solution {
    pub fn can_place_flowers(fs: Vec<i32>, n: i32) -> bool {
        let s = fs.len();
        if s == 1 {
            return fs[0] == 1;
        }

        let mut fs = fs.clone();

        let mut cnt = 0;
        for (i, f) in fs.iter().enumerate() {
            if *f != 0 {
                continue;
            }

            if i == 0 {
                if fs[i + 1] == 0 {
                    cnt += 1;
                    fs[i] = 1;
                }
            } else if i == s - 1 {
                if fs[i - 1] == 0 {
                    cnt += 1;
                    fs[i] = 1;
                }
            } else {
                if fs[i - 1] == 0 && fs[i + 1] == 0 {
                    cnt += 1;
                    fs[i] = 1;
                }
            }
        }
        return cnt >= n;
    }
}

